/// <reference types="vite/client" />
declare const GITHUB_RUNTIME_PERMANENT_NAME: string;
declare const BASE_KV_SERVICE_URL: string;

// Type declaration for the virtual PWA register module generated by vite-plugin-pwa
declare module "virtual:pwa-register" {
  export type RegisterSWOptions = {
    immediate?: boolean;
    onNeedRefresh?: () => void;
    onOfflineReady?: () => void;
    onRegistered?: (
      registration: ServiceWorkerRegistration | undefined,
    ) => void;
    onRegisterError?: (error: unknown) => void;
  };
  export function registerSW(
    options?: RegisterSWOptions,
  ): (reloadPage?: boolean) => Promise<void>;
}

// Fix spark SDK type: llmPrompt is a template tag and must accept TemplateStringsArray,
// not the narrower string[] the SDK currently declares.
interface Window {
  spark: Window["spark"] & {
    llmPrompt: (strings: TemplateStringsArray, ...values: unknown[]) => string;
  };
}
